CREATE TABLE IF NOT EXISTS budget (id INTEGER PRIMARY KEY CHECK(id=1), committed REAL NOT NULL DEFAULT 0, actual REAL NOT NULL DEFAULT 0, cap REAL NOT NULL DEFAULT 15);
INSERT OR IGNORE INTO budget(id) VALUES(1);
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, cohort TEXT NOT NULL, model TEXT NOT NULL, snapshot_at INTEGER NOT NULL, published_at INTEGER, entry_after INTEGER, status TEXT NOT NULL, snapshot TEXT NOT NULL, decision TEXT, usage TEXT, result TEXT, cost REAL NOT NULL DEFAULT 0, reservation REAL NOT NULL DEFAULT 0, latency_ms INTEGER, error TEXT);
CREATE INDEX IF NOT EXISTS runs_time ON runs(snapshot_at DESC);
CREATE TABLE IF NOT EXISTS state (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at INTEGER NOT NULL);
